import logging

from django.apps import AppConfig

logger = logging.getLogger(__name__)


class CoreConfig(AppConfig):
    default_auto_field = "django.db.models.BigAutoField"
    name = "apps.core"
    label = "core"

    # The console proxy config is now a root-owned file generated by
    # proxorchestrator-nginx-helper; it persists across reboots, so it is
    # no longer rewritten on every process start. install.sh/update.sh run
    # "manage.py update_nginx_ws" and saving the Proxmox settings refreshes it.
